package dev.forgesworn.sapflow.broadcaster

import java.io.ByteArrayOutputStream
import java.io.OutputStream
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardOpenOption.APPEND
import java.util.UUID
import java.util.concurrent.TimeUnit
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder

/** Generated bytes exercise receipts/IO only, never claim decoded MP4 proof. */
class RecordingCatalogueTest {
    @get:Rule val temporary = TemporaryFolder()
    private fun directory() = temporary.root.toPath().resolve(UUID.randomUUID().toString())
    private fun id(index: Long = 0) = RecordingCatalogue.Identity(UUID.randomUUID().toString(), UUID.randomUUID().toString(), index, CaptureProfile.DEFAULT.name)
    private fun finished(root: Path, catalogue: RecordingCatalogue, identity: RecordingCatalogue.Identity = id(), bytes: ByteArray = ByteArray(129_000) { (it % 127).toByte() }): RecordingCatalogue.Entry {
        val writer = catalogue.begin(identity)
        val file = RecordingFile(root, writer.filename)
        file.write(bytes, false); file.finish(); writer.finalised(2048)
        return catalogue.scan().single { it.segmentId == identity.segmentId }
    }
    @Test fun finalReceiptSurvivesRestartAndExportsOnlyTheSelectedBytes() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val selected = finished(root, catalogue)
        val restarted = RecordingCatalogue(root); val entry = restarted.scan().single()
        assertEquals(RecordingCatalogue.State.FINALISED, entry.state)
        assertEquals(2048L, entry.durationMs); assertEquals(selected.identity, entry.identity)
        val out = ByteArrayOutputStream()
        restarted.openExport(entry).use { assertEquals(entry.bytes, it.copyTo(out)) }
        assertArrayEquals(Files.readAllBytes(root.resolve(entry.identity!!.filename)), out.toByteArray())
        assertTrue(Files.exists(root.resolve(entry.identity.filename)))
    }
    @Test fun liveWriterAndUnknownCleanupRetainCapacityAndCannotExport() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val identity = id()
        val writer = catalogue.begin(identity); val file = RecordingFile(root, writer.filename)
        file.write(byteArrayOf(1, 2, 3), false)
        val entry = catalogue.scan().single(); assertEquals(RecordingCatalogue.State.WRITING, entry.state)
        assertThrows(IllegalStateException::class.java) { catalogue.openExport(entry, true) }
        writer.cancel() // A flag does not release file/native ownership.
        assertThrows(IllegalStateException::class.java) { RecordingCatalogue(root).begin(id()) }
        assertEquals(RecordingCatalogue.State.WRITING, catalogue.scan().single().state)
        file.abort(); writer.ownersClosed()
        val retained = RecordingCatalogue(root).scan().single()
        assertEquals(RecordingCatalogue.State.INCOMPLETE, retained.state)
        assertThrows(IllegalStateException::class.java) { catalogue.openExport(retained) }
        catalogue.openExport(retained, true).use { assertEquals(3, it.copyTo(ByteArrayOutputStream())) }
        assertThrows(IllegalStateException::class.java) { writer.finalised(10) }
    }
    @Test fun missingCorruptOrMismatchedReceiptsNeverPromoteOrphans() {
        for (kind in 0..3) {
            val root = directory(); val catalogue = RecordingCatalogue(root); val entry = finished(root, catalogue)
            val receipt = root.resolve("session-${entry.segmentId}.receipt.json")
            when (kind) {
                0 -> Files.delete(receipt)
                1 -> Files.write(receipt, "{broken".toByteArray())
                2 -> Files.write(receipt, ByteArray(4097) { 32 })
                else -> { val media = root.resolve(entry.identity!!.filename); val saved = Files.readAllBytes(media); Files.delete(media); Files.write(media, saved) }
            }
            val recovered = RecordingCatalogue(root).scan().single()
            assertEquals(RecordingCatalogue.State.ORPHAN_UNVERIFIED, recovered.state)
            assertThrows(IllegalStateException::class.java) { catalogue.openExport(recovered) }
            catalogue.openExport(recovered, true).use { it.copyTo(ByteArrayOutputStream()) }
        }
    }
    @Test fun changedSelectionAndSymlinkOrHardlinkAreRefused() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val entry = finished(root, catalogue)
        val media = root.resolve(entry.identity!!.filename)
        Files.write(media, byteArrayOf(4), APPEND)
        assertThrows(IllegalStateException::class.java) { catalogue.openExport(entry) }
        val original = root.resolve("untouched-source")
        Files.move(media, original); Files.createSymbolicLink(media, original)
        assertThrows(IllegalStateException::class.java) { catalogue.scan() }
        Files.delete(media); Files.createLink(media, original)
        assertThrows(IllegalStateException::class.java) { catalogue.scan() }
    }
    @Test fun exactPickerCannotAcquireSuccessorOrChangedReceipt() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val entry = finished(root, catalogue)
        val receipt = root.resolve("session-${entry.segmentId}.receipt.json")
        Files.write(receipt, Files.readAllBytes(receipt) + byteArrayOf(32))
        assertThrows(IllegalStateException::class.java) { catalogue.openExport(entry, true) }
        val next = finished(root, catalogue, id(1))
        assertNotEquals(entry.segmentId, next.segmentId)
        assertThrows(IllegalStateException::class.java) { catalogue.openExport(entry, true) }
    }
    @Test fun copyIsBoundedAndDetectsTruncationGrowthAndPathReplacement() {
        for (kind in 0..2) {
            val root = directory(); val catalogue = RecordingCatalogue(root); val entry = finished(root, catalogue)
            val media = root.resolve(entry.identity!!.filename)
            catalogue.openExport(entry).use { lease ->
                var calls = 0
                val output = object : OutputStream() {
                    override fun write(b: Int) = error("one-byte copy is not expected")
                    override fun write(b: ByteArray, off: Int, len: Int) {
                        assertTrue(len <= 64 * 1024)
                        if (calls++ == 0) when (kind) {
                            0 -> Files.newByteChannel(media, java.nio.file.StandardOpenOption.WRITE).use { it.truncate(1) }
                            1 -> Files.write(media, byteArrayOf(1), APPEND)
                            else -> { Files.move(media, root.resolve("original-retained")); Files.write(media, ByteArray(entry.bytes.toInt())) }
                        }
                    }
                }
                assertThrows(IllegalStateException::class.java) { lease.copyTo(output) }
            }
        }
    }
    @Test fun cancellationAndOutputFailurePreserveOriginalAndReleaseExportLease() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val entry = finished(root, catalogue)
        catalogue.openExport(entry).use { lease -> assertThrows(IllegalStateException::class.java) { lease.copyTo(ByteArrayOutputStream()) { true } } }
        catalogue.openExport(entry).use { lease -> assertThrows(java.io.IOException::class.java) { lease.copyTo(object : OutputStream() { override fun write(b: Int) { throw java.io.IOException("generated failure") }; override fun write(b: ByteArray, off: Int, len: Int) { throw java.io.IOException("generated failure") } }) } }
        assertEquals(entry.bytes, Files.size(root.resolve(entry.identity!!.filename)))
        catalogue.openExport(entry).use { it.copyTo(ByteArrayOutputStream()) }
        val writer = catalogue.begin(id()); writer.cancel(); writer.ownersClosed()
    }
    @Test fun showIdentityPersistsAcrossSegmentsWithoutClaimingWholeShowCompletion() {
        val catalogue = RecordingCatalogue(directory()); val show = catalogue.newShow(CaptureProfile.SD_480)
        val a = show.nextIdentity(); val b = show.nextIdentity()
        assertEquals(a.showId, b.showId); assertEquals(0, a.segmentIndex); assertEquals(1, b.segmentIndex)
        assertNotEquals(a.segmentId, b.segmentId); assertEquals(CaptureProfile.SD_480.name, b.profileId)
        assertThrows(IllegalArgumentException::class.java) { RecordingCatalogue.Identity("../unsafe", a.showId, 0, a.profileId) }
    }
    @Test fun catalogueCapacityIsVisibleAndPreservesAllFiles() {
        val root = directory(); val catalogue = RecordingCatalogue(root)
        repeat(257) { Files.write(root.resolve(id().filename), byteArrayOf(1)) }
        assertThrows(IllegalStateException::class.java) { catalogue.scan() }
        assertEquals(257, Files.list(root).use { it.count() })
    }
    @Test fun scansAndRejectedLocalOwnersCannotReleaseTheActualProcessLock() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val identity = id()
        val writer = catalogue.begin(identity); val file = RecordingFile(root, writer.filename)
        file.write(byteArrayOf(1, 2, 3), false)
        var lockPath = root.resolve(".recording-writer.lock")
        fun childCanLock(): Boolean {
            // Independent OS fcntl oracle, not Java's same-VM overlap table.
            val script = "import fcntl,sys\nf=open(sys.argv[1], 'r+b')\ntry:\n fcntl.lockf(f,fcntl.LOCK_EX|fcntl.LOCK_NB)\n print('open')\nexcept BlockingIOError:\n print('blocked')\n"
            val child = ProcessBuilder("python3", "-c", script, lockPath.toString()).redirectErrorStream(true).start()
            try {
                assertTrue(child.waitFor(5, TimeUnit.SECONDS)); assertEquals(0, child.exitValue())
                val output = child.inputStream.readNBytes(128).toString(Charsets.US_ASCII).trim()
                assertTrue(output in listOf("open", "blocked")); return output == "open"
            } finally { if (child.isAlive) { child.destroyForcibly(); child.waitFor(5, TimeUnit.SECONDS) } }
        }
        try {
            assertFalse(childCanLock())
            repeat(3) {
                assertEquals(RecordingCatalogue.State.WRITING, RecordingCatalogue(root).scan().single().state)
                assertThrows(IllegalStateException::class.java) { RecordingCatalogue(root).begin(id()) }
                assertFalse(childCanLock())
            }
            val otherRoot = directory(); val other = RecordingCatalogue(otherRoot)
            val moved = otherRoot.resolve(".recording-writer.lock")
            Files.move(lockPath, moved); lockPath = moved
            assertThrows(IllegalStateException::class.java) { other.begin(id()) }
            assertFalse("renamed lock aliases must be refused before opening another FD", childCanLock())
            writer.cancel(); assertFalse(childCanLock())
        } finally { file.abort(); writer.ownersClosed() }
        assertTrue(childCanLock())
        val next = catalogue.begin(id()); next.cancel(); next.ownersClosed()
    }
    @Test fun cancelledFinishCannotPromoteAnActualForcedFile() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val writer = catalogue.begin(id())
        val file = RecordingFile(root, writer.filename); file.write(byteArrayOf(1, 2), false)
        writer.cancel(); file.finish()
        assertThrows(IllegalStateException::class.java) { writer.finalised(10) }
        writer.ownersClosed()
        assertTrue(writer.cleanupComplete)
        assertEquals(RecordingCatalogue.State.INCOMPLETE, catalogue.scan().single().state)
    }
    @Test fun actualExportCloseReceiptIsRequiredBeforeAnotherOwner() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val entry = finished(root, catalogue)
        val export = catalogue.openExport(entry)
        assertTrue(catalogue.cleanupRetained)
        assertFalse(catalogue.cleanupUncertain)
        assertFalse(export.cleanupComplete)
        assertThrows(IllegalStateException::class.java) { catalogue.begin(id()) }
        export.copyTo(ByteArrayOutputStream()); assertFalse(export.cleanupComplete)
        export.close(); assertTrue(export.cleanupComplete)
        assertFalse(catalogue.cleanupRetained)
        export.close(); assertTrue(export.cleanupComplete)
        val next = catalogue.begin(id()); next.cancel(); next.ownersClosed()
    }
    @Test fun failedCloseCannotBecomeSuccessfulThroughARepeatedNoOp() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val entry = finished(root, catalogue)
        val input = java.nio.channels.FileChannel.open(root.resolve(entry.identity!!.filename), java.nio.file.StandardOpenOption.READ)
        var releases = 0
        val export = catalogue.Export(entry, input, { releases++; throw java.io.IOException("generated failed close") }, { true })
        assertThrows(java.io.IOException::class.java) { export.close() }
        assertFalse(export.cleanupComplete); assertFalse(input.isOpen)
        assertThrows(java.io.IOException::class.java) { export.close() }
        assertFalse(export.cleanupComplete); assertEquals(1, releases)
    }
    @Test fun unknownInputCloseNeverReleasesSharedLease() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val entry = finished(root, catalogue)
        val input = java.nio.channels.FileChannel.open(root.resolve(entry.identity!!.filename), java.nio.file.StandardOpenOption.READ)
        var releases = 0
        var uncertain = false
        val export = catalogue.Export(entry, input, { releases++ }, { true }, { throw java.io.IOException("generated input close failure") }, { uncertain = true })
        try {
            assertThrows(java.io.IOException::class.java) { export.close() }
            assertTrue(input.isOpen); assertFalse(export.cleanupComplete); assertEquals(0, releases)
            assertTrue(uncertain)
            assertThrows(java.io.IOException::class.java) { export.close() }
            assertEquals(0, releases)
        } finally { input.close() }
    }
    @Test fun healthyWriterAndOrdinaryBusyAreNotUncertainCleanup() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val writer = catalogue.begin(id())
        assertTrue(catalogue.cleanupRetained); assertFalse(catalogue.cleanupUncertain)
        catalogue.scan()
        assertThrows(IllegalStateException::class.java) { RecordingCatalogue(root).begin(id()) }
        assertFalse(RecordingCatalogue(root).cleanupUncertain)
        writer.retainUncertainCleanup()
        assertTrue(RecordingCatalogue(root).cleanupUncertain)
        writer.cancel(); writer.ownersClosed()
        assertFalse(catalogue.cleanupRetained); assertFalse(catalogue.cleanupUncertain)
    }
    @Test fun capacityPreflightRefusesFullAndLiveWritersWithoutCreatingSegments() {
        val root = directory(); val catalogue = RecordingCatalogue(root)
        catalogue.checkRecordingCapacity()
        assertTrue(catalogue.scan().isEmpty()); assertFalse(catalogue.cleanupRetained)
        val writer = catalogue.begin(id())
        val busy = assertThrows(RecordingCatalogue.CatalogueFailure::class.java) { catalogue.checkRecordingCapacity() }
        assertEquals(RecordingCatalogue.Failure.BUSY, busy.reason); assertFalse(catalogue.cleanupUncertain)
        writer.cancel(); writer.ownersClosed()
        repeat(255) { Files.write(root.resolve(id().filename), byteArrayOf(1)) }
        assertEquals(256, catalogue.scan().size)
        val full = assertThrows(RecordingCatalogue.CatalogueFailure::class.java) { catalogue.checkRecordingCapacity() }
        assertEquals(RecordingCatalogue.Failure.CAPACITY, full.reason)
        assertFalse(catalogue.cleanupRetained); assertFalse(catalogue.cleanupUncertain)
        assertEquals(256, catalogue.scan().size)
    }
    @Test fun audioShowPersistsDistinctTopologyWithoutInventingVideoQuality() {
        val root = directory(); val catalogue = RecordingCatalogue(root)
        val show = catalogue.newShow(CaptureIntent.AudioOnly48kMono)
        val identity = show.nextIdentity()
        assertEquals("AUDIO_ONLY_48K_MONO", identity.profileId)
        val writer = catalogue.begin(identity)
        Files.write(root.resolve(identity.filename), byteArrayOf(1, 2, 3))
        writer.finalised(1000)
        val entry = catalogue.scan().single()
        assertEquals(identity, entry.identity); assertEquals(RecordingCatalogue.State.FINALISED, entry.state)
        assertEquals(identity.showId, show.nextIdentity().showId)
    }
    private fun sourcePermit(writer: RecordingCatalogue.Writer, gate: RecordingSourceGate): RecordingSourceGate.FinishPermit {
        val owner = Any(); val prepared = Any(); val generation = Any()
        val key = gate.bindProducer(owner, prepared, 7); val recorder = gate.bindRecorder(Any())
        gate.generationStarted(key, generation); gate.generationClosed(key, generation, 1024, true, true)
        writer.bindSource(recorder); recorder.accepted(); recorder.consumed()
        return checkNotNull(recorder.drained(gate.terminal(key, owner, prepared, 7)))
    }
    @Test fun delayedSourceLossCannotPromoteAnActualForcedAndClosedFile() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val writer = catalogue.begin(id()); val gate = RecordingSourceGate(7)
        val permit = sourcePermit(writer, gate); val oldCanFinish = true
        val file = RecordingFile(root, writer.filename); file.write(byteArrayOf(1, 2, 3, 4), false); file.finish()
        gate.fail(); assertTrue(oldCanFinish)
        assertThrows(IllegalStateException::class.java) { writer.finalised(10, permit) }
        writer.ownersClosed(); assertTrue(writer.cleanupComplete)
        assertEquals(RecordingCatalogue.State.INCOMPLETE, catalogue.scan().single().state)
    }
    @Test fun exactSourceAndDrainedFrontierAuthoriseOneRealCatalogueCommit() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val writer = catalogue.begin(id()); val gate = RecordingSourceGate(7)
        val permit = sourcePermit(writer, gate)
        val file = RecordingFile(root, writer.filename); file.write(byteArrayOf(5, 6, 7, 8), false); file.finish()
        writer.finalised(10, permit); assertTrue(writer.cleanupComplete)
        assertEquals(RecordingCatalogue.State.FINALISED, catalogue.scan().single().state)
        assertThrows(IllegalStateException::class.java) { writer.finalised(10, permit) }
        assertEquals(RecordingCatalogue.State.FINALISED, catalogue.scan().single().state)
    }

    @Test fun failedSourceCanCloseAnIncompletePrefixWithoutConsumingItsPermit() {
        val root = directory(); val catalogue = RecordingCatalogue(root); val writer = catalogue.begin(id()); val gate = RecordingSourceGate(7)
        val permit = sourcePermit(writer, gate); val bytes = byteArrayOf(9, 10, 11, 12)
        val file = RecordingFile(root, writer.filename); file.write(bytes, false)
        gate.fail() // Source loss precedes the distinct prefix-only force/close.
        file.finish(); writer.cancel(); writer.ownersClosed()
        assertTrue(writer.cleanupComplete); assertArrayEquals(bytes, Files.readAllBytes(root.resolve(writer.filename)))
        assertEquals(RecordingCatalogue.State.INCOMPLETE, catalogue.scan().single().state)
        assertThrows(IllegalStateException::class.java) { writer.finalised(10, permit) }
        assertEquals(RecordingCatalogue.State.INCOMPLETE, catalogue.scan().single().state)
    }

    @Test fun boundWriterRefusesUntypedFinalisationAndForeignRebinding() {
        val root = directory(); val catalogue = RecordingCatalogue(root)
        val writer = catalogue.begin(id()); val gate = RecordingSourceGate(7)
        val permit = sourcePermit(writer, gate)
        val file = RecordingFile(root, writer.filename); file.write(byteArrayOf(1, 3, 5), false); file.finish()
        assertThrows(IllegalStateException::class.java) { writer.finalised(10) }
        val foreign = RecordingSourceGate(7).bindRecorder(Any())
        assertThrows(IllegalStateException::class.java) { writer.bindSource(foreign) }
        val foreignRoot = directory(); val foreignCatalogue = RecordingCatalogue(foreignRoot)
        val foreignWriter = foreignCatalogue.begin(id())
        val foreignPermit = sourcePermit(foreignWriter, RecordingSourceGate(7))
        assertThrows(IllegalStateException::class.java) { writer.finalised(10, foreignPermit) }
        writer.finalised(10, permit)
        assertEquals(RecordingCatalogue.State.FINALISED, catalogue.scan().single().state)
        foreignWriter.cancel(); foreignWriter.ownersClosed()
    }

}
